// ============================================================
// Edge Impulse signal callback
// ============================================================

static int get_signal_data(size_t offset, size_t length, float *out_ptr)
{
    for (size_t i = 0; i < length; i++)
    {
        out_ptr[i] = features[offset + i];
    }

    return 0;
}

// ============================================================
// Main
// ============================================================

int main()
{
    std::cout << "=========================================\n";
    std::cout << " JARVIS TinyML Model Test\n";
    std::cout << "=========================================\n\n";

    const size_t feature_count =
        sizeof(features) / sizeof(features[0]);

    std::cout << "Features in array: "
              << feature_count << "\n";

    std::cout << "Expected features: "
              << EI_CLASSIFIER_DSP_INPUT_FRAME_SIZE << "\n";

    if (feature_count != EI_CLASSIFIER_DSP_INPUT_FRAME_SIZE)
    {
        std::cout << "\nERROR: Feature count does not match "
                     "the model input size!\n";

        return 1;
    }

    // Create Edge Impulse signal
    signal_t signal;

    signal.total_length = feature_count;
    signal.get_data = get_signal_data;

    // Create result structure
    ei_impulse_result_t result = {};

    std::cout << "\nRunning inference...\n\n";

    EI_IMPULSE_ERROR result_code =
        run_classifier(&signal, &result, false);

    if (result_code != EI_IMPULSE_OK)
    {
        std::cout << "ERROR: run_classifier() failed.\n";
        std::cout << "Error code: "
                  << static_cast<int>(result_code)
                  << "\n";

        return 1;
    }

    std::cout << "Inference successful!\n\n";

    std::cout << "Predictions:\n";
    std::cout << "-----------------------------\n";

    for (size_t i = 0; i < EI_CLASSIFIER_LABEL_COUNT; i++)
    {
        std::cout
            << result.classification[i].label
            << ": "
            << result.classification[i].value
            << "\n";
    }

    std::cout << "\n-----------------------------\n";

    std::cout << "Timing:\n";
    std::cout << "DSP: "
              << result.timing.dsp
              << " ms\n";

    std::cout << "Classification: "
              << result.timing.classification
              << " ms\n";

    std::cout << "Postprocessing: "
              << result.timing.postprocessing
              << " ms\n";

    std::cout << "\nTest complete.\n";

    return 0;
}